def solve2(inp):
    h=len(inp); w=len(inp[0]); out=[r[:] for r in inp]
    seen=[[False]*w for _ in range(h)]
    for i in range(h):
        for j in range(w):
            if inp[i][j]!=8 or True: continue
    # find rectangles: a border color c forms rectangle if it has top/bottom run len>=3 at rows i..i+h-1 and sides
    recs=[]
    used=set()
    for i in range(h):
        for j in range(w):
            c=inp[i][j]
            if c==0 or c==8 or c==5: continue
            if (i,j) in used: continue
            # candidate rectangle: extend down and right
            H=i
            while H<h and inp[H][j]==c and inp[H][j+1]==c and inp[H][j+2]==c and H-i<10: H+=1
            W=j
            while W<w and inp[i][W]==c and inp[i+1][W]==c and inp[i+2][W]==c and W-j<10: W+=1
            H-=1; W-=1
            if H-i>=1 and W-j>=1:
                # verify full rect
                ok=True
                for x in range(i,H+1):
                    if inp[x][j]!=c or inp[x][W]!=c: ok=False
                for y in range(j,W+1):
                    if inp[i][y]!=c or inp[H][y]!=c: ok=False
                if not ok:
                    used.add((i,j)); continue
                interior=(H-i-1)*(W-j-1)
                if interior<=0: 
                    used.add((i,j)); continue
                # interior uniform non-c? just check interior colors all equal
                ints={inp[x][y] for x in range(i+1,H) for y in range(j+1,W)}
                if len(ints)!=1:
                    used.add((i,j)); continue
                inter=list(ints)[0]
                n=interior
                if interior%2: fill=7
                else: fill=2
                used.add((i,j))
                for x in range(i+1,H):
                    for y in range(j+1,W):
                        if inp[x][y]!=inter and inp[x][y]!=fill: pass  # no-op; we overwrite interiors only
                # recolor interior
                for x in range(i+1,H):
                    for y in range(j+1,W):
                        out[x][y]=fill
    return out
